use xiom.io;

use xiom.string;
fn main() -> Int {
  let success: Result[Int, Str] = Ok(200);
  let failure: Result[Int, Str] = Err("Server error");

  let msg1 = match success {
    Ok(code) => "Status: " + to_string(code),
    Err(e) => "Error: " + e,
  };
  let msg2 = match failure {
    Ok(code) => "Status: " + to_string(code),
    Err(e) => "Error: " + e,
  };

  io.println(msg1.to_str());
  io.println(msg2.to_str());
  return 0;
}
